const v2 = { messageId: '1', payload: JSON.stringify({ version: 2, sensorId: 's2', value: 150, timestamp: 1001, location: 'A' }) };

consumer.process(v1);
consumer.process(v2);
assert(defaultSink.calls === 1);
assert(alertsSink.calls === 1);
